// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 wei, 1000 ether);

        (, uint256 before) = c.Acc(actor);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(0);

        (, uint256 afterBal) = c.Acc(actor);
        assertTrue(afterBal == before + amount, "balance must grow by deposited amount");
    }
}
